-- Modify "products" table
ALTER TABLE "products" ADD COLUMN "cover_protected" boolean NOT NULL DEFAULT false, ADD COLUMN "description_protected" boolean NOT NULL DEFAULT false;
-- Create "product_content_batches" table
CREATE TABLE "product_content_batches" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "token" character varying NOT NULL, "actor_id" bigint NOT NULL, "payload" jsonb NOT NULL, "expires_at" timestamptz NOT NULL, "completed" boolean NOT NULL DEFAULT false, "matched" integer NOT NULL DEFAULT 0, "changed" integer NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create index "product_content_batches_token_key" to table: "product_content_batches"
CREATE UNIQUE INDEX "product_content_batches_token_key" ON "product_content_batches" ("token");
